import functools
def repeat(n):
    def deco(func):
        @functools.wraps(func)
        def wrapper(*a, **k):
            for _ in range(n):
                func(*a, **k)
        return wrapper
    return deco

@repeat(2)
def hey():
    print('hey')

hey()

